begin;
create schema if not exists auth_private;
revoke all on schema auth_private from public, anon, authenticated;

create or replace function auth_private.handle_new_user_profile()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_display_name text;
begin
  v_display_name := nullif(
    left(regexp_replace(coalesce(new.raw_user_meta_data ->> 'full_name', ''), '[[:cntrl:]]', '', 'g'), 80),
    ''
  );

  insert into public.profiles (id, display_name, locale, timezone)
  values (new.id, v_display_name, 'id-ID', 'Asia/Jakarta')
  on conflict (id) do nothing;

  return new;
end;
$$;

revoke all on function auth_private.handle_new_user_profile() from public, anon, authenticated;

drop trigger if exists moreai_auth_user_profile_created on auth.users;
create trigger moreai_auth_user_profile_created
after insert on auth.users
for each row execute function auth_private.handle_new_user_profile();

drop policy if exists profiles_update_own on public.profiles;
create policy profiles_update_own
on public.profiles
for update
to authenticated
using ((select auth.uid()) = id)
with check ((select auth.uid()) = id);

insert into public.profiles (id, display_name, locale, timezone)
select
  u.id,
  nullif(left(regexp_replace(coalesce(u.raw_user_meta_data ->> 'full_name', ''), '[[:cntrl:]]', '', 'g'), 80), ''),
  'id-ID',
  'Asia/Jakarta'
from auth.users u
on conflict (id) do nothing;
commit;

-- Preserve immutable metadata for every committed workspace file version.
-- Object bytes remain in the private workspace Storage bucket; this table is metadata only.
create table if not exists public.agent_workspace_file_versions (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  path text not null check (length(path) between 1 and 512),
  version bigint not null check (version > 0),
  storage_path text not null,
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  size_bytes bigint not null check (size_bytes between 0 and 2000000),
  committed_at timestamptz not null,
  recorded_at timestamptz not null default now(),
  unique (workspace_id, path, version)
);

create index if not exists agent_workspace_file_versions_owner_path_idx
  on public.agent_workspace_file_versions (user_id, workspace_id, path, version desc);

alter table public.agent_workspace_file_versions enable row level security;
drop policy if exists agent_workspace_file_versions_server_only on public.agent_workspace_file_versions;
create policy agent_workspace_file_versions_server_only
  on public.agent_workspace_file_versions for all to anon, authenticated
  using (false) with check (false);
revoke all on public.agent_workspace_file_versions from public, anon, authenticated;
grant all on public.agent_workspace_file_versions to service_role;

create or replace function public.moreai_record_workspace_file_version()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.version > old.version
     and old.version > 0
     and old.storage_path is not null
     and old.sha256 is not null
     and old.size_bytes is not null then
    insert into public.agent_workspace_file_versions (
      workspace_id, user_id, path, version, storage_path, sha256, size_bytes, committed_at
    ) values (
      old.workspace_id, old.user_id, old.path, old.version,
      old.storage_path, old.sha256, old.size_bytes, old.updated_at
    ) on conflict (workspace_id, path, version) do nothing;
  end if;
  return new;
end;
$$;

drop trigger if exists agent_workspace_file_versions_archive on public.agent_workspace_files;
create trigger agent_workspace_file_versions_archive
  before update of version on public.agent_workspace_files
  for each row execute function public.moreai_record_workspace_file_version();

revoke all on function public.moreai_record_workspace_file_version() from public, anon, authenticated;

-- Align the persisted approval allowlist with the canonical OpenManus runtime tool keys.
-- Additive/forward-only: preserve existing aliases and all approval/RLS behavior.
alter table public.agent_tool_approvals
  drop constraint if exists agent_tool_approvals_tool_key_check;

alter table public.agent_tool_approvals
  add constraint agent_tool_approvals_tool_key_check
  check (tool_key in (
    'bash','python_execute','browser_use','planning_step',
    'browser','file_read','file_write','file_edit','workspace_restore_version'
  ));

create or replace function public.moreai_request_tool_approval(
  p_run_id uuid, p_user_id uuid, p_tool_key text, p_arguments_hash text,
  p_summary text, p_expires_in_seconds integer default 900
) returns uuid
language plpgsql security definer set search_path = public, pg_temp
as $$
declare v_id uuid;
begin
  if p_tool_key not in (
       'bash','python_execute','browser_use','planning_step',
       'browser','file_read','file_write','file_edit','workspace_restore_version'
     )
     or p_arguments_hash !~ '^[0-9a-f]{64}$'
     or p_expires_in_seconds < 60 or p_expires_in_seconds > 3600
     or char_length(p_summary) not between 1 and 1000 then
    raise exception 'invalid_tool_approval_request' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.agent_runs r
    where r.id=p_run_id and r.user_id=p_user_id
  ) then
    raise exception 'approval_run_owner_mismatch' using errcode = '42501';
  end if;
  update public.agent_tool_approvals
     set status='expired'
   where run_id=p_run_id and tool_key=p_tool_key and arguments_hash=p_arguments_hash
     and status in ('pending','approved') and expires_at <= now();
  select id into v_id from public.agent_tool_approvals
   where run_id=p_run_id and tool_key=p_tool_key and arguments_hash=p_arguments_hash
     and status in ('pending','approved') and expires_at > now()
   order by requested_at desc
   limit 1;
  if v_id is not null then return v_id; end if;
  insert into public.agent_tool_approvals(run_id,user_id,tool_key,arguments_hash,summary,expires_at)
  values(p_run_id,p_user_id,p_tool_key,p_arguments_hash,p_summary,now()+make_interval(secs=>p_expires_in_seconds))
  returning id into v_id;
  return v_id;
end;
$$;

revoke all on function public.moreai_request_tool_approval(uuid,uuid,text,text,text,integer)
  from public, anon, authenticated;
grant execute on function public.moreai_request_tool_approval(uuid,uuid,text,text,text,integer)
  to service_role;

create table if not exists public.customer_learning_progress (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  module_key text not null check (module_key ~ '^[a-z0-9][a-z0-9_-]{0,79}$'),
  lesson_key text not null check (length(lesson_key) between 1 and 512),
  completed_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(user_id,module_key,lesson_key)
);
create index if not exists customer_learning_progress_user_idx
  on public.customer_learning_progress(user_id,module_key,completed_at desc);
alter table public.customer_learning_progress enable row level security;
drop policy if exists customer_learning_progress_server_only on public.customer_learning_progress;
create policy customer_learning_progress_server_only on public.customer_learning_progress
  for all to anon,authenticated using(false) with check(false);
revoke all on public.customer_learning_progress from public,anon,authenticated;
grant all on public.customer_learning_progress to service_role;

create or replace function public.moreai_set_customer_learning_progress(
 p_user_id uuid,p_module_key text,p_lesson_key text,p_completed boolean
) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_row public.customer_learning_progress%rowtype;
begin
 if p_module_key !~ '^[a-z0-9][a-z0-9_-]{0,79}$' or char_length(p_lesson_key) not between 1 and 512 then
   raise exception 'invalid_learning_progress_key' using errcode='22023';
 end if;
 if p_completed then
   insert into public.customer_learning_progress(user_id,module_key,lesson_key,completed_at,updated_at)
   values(p_user_id,p_module_key,p_lesson_key,now(),now())
   on conflict(user_id,module_key,lesson_key) do update set completed_at=now(),updated_at=now()
   returning * into v_row;
   return jsonb_build_object('module_key',v_row.module_key,'lesson_key',v_row.lesson_key,'completed',true,'completed_at',v_row.completed_at);
 else
   delete from public.customer_learning_progress
    where user_id=p_user_id and module_key=p_module_key and lesson_key=p_lesson_key;
   return jsonb_build_object('module_key',p_module_key,'lesson_key',p_lesson_key,'completed',false,'completed_at',null);
 end if;
end; $$;
revoke all on function public.moreai_set_customer_learning_progress(uuid,text,text,boolean) from public,anon,authenticated;
grant execute on function public.moreai_set_customer_learning_progress(uuid,text,text,boolean) to service_role;

-- Customer-owned workspace upload contract.
-- Storage objects are immutable and version-addressed. The RPC commits metadata with CAS
-- and the existing version-history trigger archives the previous committed version.
create table if not exists public.customer_workspace_upload_idempotency (
  user_id uuid not null references auth.users(id) on delete cascade,
  idempotency_key text not null check (length(idempotency_key) between 12 and 128),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  path text not null check (length(path) between 1 and 512),
  expected_version bigint not null check (expected_version >= 0),
  storage_path text not null,
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  size_bytes bigint not null check (size_bytes between 1 and 2000000),
  result jsonb,
  committed_at timestamptz,
  created_at timestamptz not null default now(),
  primary key (user_id, idempotency_key)
);

create index if not exists customer_workspace_upload_idempotency_workspace_idx
  on public.customer_workspace_upload_idempotency (workspace_id, user_id, created_at desc);

alter table public.customer_workspace_upload_idempotency enable row level security;
drop policy if exists customer_workspace_upload_idempotency_server_only
  on public.customer_workspace_upload_idempotency;
create policy customer_workspace_upload_idempotency_server_only
  on public.customer_workspace_upload_idempotency for all to anon, authenticated
  using (false) with check (false);
revoke all on public.customer_workspace_upload_idempotency from public, anon, authenticated;
grant all on public.customer_workspace_upload_idempotency to service_role;

create or replace function public.moreai_customer_workspace_commit_upload(
  p_user_id uuid,
  p_workspace_id uuid,
  p_path text,
  p_expected_version bigint,
  p_idempotency_key text,
  p_storage_path text,
  p_sha256 text,
  p_size_bytes bigint
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_workspace public.workspaces%rowtype;
  v_file public.agent_workspace_files%rowtype;
  v_intent public.customer_workspace_upload_idempotency%rowtype;
  v_next_version bigint;
  v_expected_storage_path text;
  v_result jsonb;
begin
  if p_user_id is null or p_workspace_id is null
     or p_path is null or length(p_path) not between 1 and 512
     or p_expected_version is null or p_expected_version < 0
     or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_size_bytes is null or p_size_bytes not between 1 and 2000000 then
    raise exception 'workspace_upload_arguments_invalid' using errcode = '22023';
  end if;

  select * into v_workspace
    from public.workspaces
   where id = p_workspace_id and status = 'active'
     and (owner_user_id = p_user_id or exists (
       select 1 from public.workspace_members m
        where m.workspace_id = p_workspace_id
          and m.user_id = p_user_id and m.status = 'active'
     ));
  if not found then
    raise exception 'workspace_membership_required' using errcode = '42501';
  end if;

  v_next_version := p_expected_version + 1;
  v_expected_storage_path := p_user_id::text || '/workspaces/' ||
    p_workspace_id::text || '/versions/' || v_next_version::text || '/' || p_path;
  if p_storage_path is distinct from v_expected_storage_path then
    raise exception 'workspace_upload_storage_path_invalid' using errcode = '22023';
  end if;

  insert into public.customer_workspace_upload_idempotency (
    user_id, idempotency_key, workspace_id, path, expected_version,
    storage_path, sha256, size_bytes
  ) values (
    p_user_id, p_idempotency_key, p_workspace_id, p_path, p_expected_version,
    p_storage_path, p_sha256, p_size_bytes
  ) on conflict (user_id, idempotency_key) do nothing;

  select * into v_intent
    from public.customer_workspace_upload_idempotency
   where user_id = p_user_id and idempotency_key = p_idempotency_key
   for update;

  if v_intent.workspace_id <> p_workspace_id
     or v_intent.path <> p_path
     or v_intent.expected_version <> p_expected_version
     or v_intent.storage_path <> p_storage_path
     or v_intent.sha256 <> p_sha256
     or v_intent.size_bytes <> p_size_bytes then
    raise exception 'workspace_upload_idempotency_key_reused' using errcode = '22023';
  end if;

  if v_intent.committed_at is not null then
    return coalesce(v_intent.result, '{}'::jsonb) || jsonb_build_object('replayed', true);
  end if;

  insert into public.agent_workspace_files (workspace_id, user_id, path, version)
  values (p_workspace_id, p_user_id, p_path, 0)
  on conflict (workspace_id, path) do nothing;

  update public.agent_workspace_files
     set version = v_next_version,
         storage_path = p_storage_path,
         sha256 = p_sha256,
         size_bytes = p_size_bytes,
         updated_at = now()
   where workspace_id = p_workspace_id
     and path = p_path
     and version = p_expected_version
     and pending_token is null
     and pending_version is null
     and pending_run_id is null
     and deleted_at is null
  returning * into v_file;

  if not found then
    raise exception 'workspace_version_conflict_or_write_in_progress' using errcode = '40001';
  end if;

  v_result := jsonb_build_object(
    'workspace_id', p_workspace_id,
    'file_id', v_file.id,
    'path', v_file.path,
    'version', v_file.version,
    'storage_path', v_file.storage_path,
    'sha256', v_file.sha256,
    'size_bytes', v_file.size_bytes,
    'updated_at', v_file.updated_at,
    'replayed', false
  );

  update public.customer_workspace_upload_idempotency
     set result = v_result, committed_at = now()
   where user_id = p_user_id and idempotency_key = p_idempotency_key;

  return v_result;
end;
$function$;

revoke all on function public.moreai_customer_workspace_commit_upload(uuid, uuid, text, bigint, text, text, text, bigint)
  from public, anon, authenticated;
grant execute on function public.moreai_customer_workspace_commit_upload(uuid, uuid, text, bigint, text, text, text, bigint)
  to service_role;

-- Additive migration: atomically persist a user chat message and its durable agent run.
-- No table reset, destructive DDL, or RLS relaxation.
create or replace function public.moreai_enqueue_chat_run(
    p_user_id uuid,
    p_conversation_id uuid,
    p_content text,
    p_agent_key text,
    p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
begin
    if p_user_id is null
       or p_conversation_id is null
       or p_content is null
       or length(btrim(p_content)) = 0
       or length(p_content) > 100000
       or p_agent_key is null
       or p_idempotency_key is null
       or length(p_idempotency_key) < 12
       or length(p_idempotency_key) > 128
       or p_agent_key not in ('manus', 'planning', 'toolcall') then
        raise exception 'invalid chat enqueue request' using errcode = '22023';
    end if;

    select *
      into v_conversation
      from public.conversations
     where id = p_conversation_id
       and user_id = p_user_id
     for update;

    if not found then
        raise exception 'conversation not found' using errcode = '42501';
    end if;

    select *
      into v_run
      from public.agent_runs
     where user_id = p_user_id
       and idempotency_key = p_idempotency_key;

    if found then
        return pg_catalog.jsonb_build_object(
            'run', pg_catalog.to_jsonb(v_run),
            'message', null,
            'replayed', true
        );
    end if;

    insert into public.conversation_messages (
        conversation_id, user_id, role, content, metadata
    ) values (
        p_conversation_id, p_user_id, 'user', p_content, '{}'::jsonb
    )
    returning * into v_message;

    insert into public.agent_runs (
        user_id, workspace_id, conversation_id, status,
        idempotency_key, input, max_attempts
    ) values (
        p_user_id,
        v_conversation.workspace_id,
        p_conversation_id,
        'queued',
        p_idempotency_key,
        pg_catalog.jsonb_build_object(
            'prompt', p_content,
            'agent_key', p_agent_key,
            'conversation_id', p_conversation_id,
            'message_id', v_message.id
        ),
        3
    )
    returning * into v_run;

    update public.conversation_messages
       set run_id = v_run.id
     where id = v_message.id
       and user_id = p_user_id;
    v_message.run_id := v_run.id;

    return pg_catalog.jsonb_build_object(
        'run', pg_catalog.to_jsonb(v_run),
        'message', pg_catalog.to_jsonb(v_message),
        'replayed', false
    );
end;
$function$;

revoke all on function public.moreai_enqueue_chat_run(uuid, uuid, text, text, text) from public;
revoke all on function public.moreai_enqueue_chat_run(uuid, uuid, text, text, text) from anon;
revoke all on function public.moreai_enqueue_chat_run(uuid, uuid, text, text, text) from authenticated;
grant execute on function public.moreai_enqueue_chat_run(uuid, uuid, text, text, text) to service_role;
